// All-cell initial physical-source norms after complete interface qualification.
#define main transition_localization_reference_not_invoked
#include "diagnose_transition_jets.cpp"
#undef main
#include "transition_background_projection.hpp"
#include "transition_orthogonal_background_jet.hpp"
using J=cubed_sphere::Jet;using Original=h::TransitionBackgroundJet;using Orth=h::TransitionOrthogonalBackgroundJet;
Real Scale(const Grid&g,size_t p){Real maxrow=0;for(int A=0;A<3;++A){Real sum=0;for(int a=0;a<3;++a)sum+=g.geometry[p].J[A][a]*g.geometry[p].J[A][a];maxrow=std::max(maxrow,std::sqrt(sum));}return 1/(g.n*maxrow);}
J SinJet(const J&a){J b(std::sin(a.f));for(int i=0;i<3;++i){b.d[i]=std::cos(a.f)*a.d[i];for(int j=0;j<3;++j)b.h[i][j]=std::cos(a.f)*a.h[i][j]-std::sin(a.f)*a.d[i]*a.d[j];}return b;}
J Delta(int mode,const Point&x){J y[3];for(int a=0;a<3;++a)y[a]=J::Variable(x[a],a);if(mode==0)return J(1);if(mode==1)return y[0]+J(.3)*y[1]-J(.7)*y[2]+y[0]*y[0]+J(.7)*y[0]*y[1]+J(2)*y[2]*y[2];if(mode==2||mode==3)return J(0);if(mode==4)return J(.001)*SinJet(J(3)*y[0])*SinJet(J(2)*y[1])+J(.001)*y[2]*y[2]*y[2];if(mode==5)return J(.001)*y[0]*y[1]/(y[0]*y[0]+y[1]*y[1]+y[2]*y[2]);if(mode==6)return J(.1)*SinJet(J(12)*y[0]+J(7)*y[1]-J(5)*y[2]);return J(.2)*cubed_sphere::Log(cubed_sphere::Power(y[0]*y[0]+y[1]*y[1]+y[2]*y[2],.5)+J(.17));}
Real Coefficient(int mode){return mode<2?0:(mode==3?.7:1);}
std::array<Real,24> PhysicalQuantities(U u,const Point&x){const auto omega=h::CompositeOmegaAt(x.data(),u);const auto c=h::EvolvedConstraints(u,omega);const auto p=h::ConformalRHS(u,omega,Real(4),Real(-.99),true);h::Z4cRHS<Real> rhs{};if(!c.valid||!h::AssembleInterior(p,omega.omega,rhs))throw std::runtime_error("invalid independent initial source");std::array<Real,24> out{};out[0]=c.hamiltonian;out[1]=std::sqrt(c.momentum_conformal_norm2);out[2]=rhs.chi;out[3]=rhs.trace;out[4]=rhs.theta;out[5]=h::WormholeLapseRate(x.data(),u);for(int t=0;t<6;++t){out[6+t]=rhs.metric[Engine::tensor_i[t]][Engine::tensor_j[t]];out[12+t]=rhs.a[Engine::tensor_i[t]][Engine::tensor_j[t]];}for(int i=0;i<3;++i){out[18+i]=rhs.lambda[i];out[21+i]=.005/.02*h::ReferenceTelegraphSupport(Radius(x.data()),.8,.24).value*u.alpha.d[i];}for(Real v:out)if(!std::isfinite(v))throw std::runtime_error("nonfinite full initial source");return out;}

J ModeJet(int mode,const Point&x){J y[3];for(int a=0;a<3;++a)y[a]=J::Variable(x[a],a);J r=cubed_sphere::Power(y[0]*y[0]+y[1]*y[1]+y[2]*y[2],.5);
 if(mode==0)return J(1);if(mode==1)return Delta(1,x);if(mode==2)return J(1.09)*cubed_sphere::Log(r);if(mode==3)return J(.5)*r;
 if(mode==4||mode==8){J t=J(12)*y[0]+J(7)*y[1]-J(5)*y[2],c(std::cos(t.f));for(int a=0;a<3;++a){c.d[a]=-std::sin(t.f)*t.d[a];for(int b=0;b<3;++b)c.h[a][b]=-std::sin(t.f)*t.h[a][b]-std::cos(t.f)*t.d[a]*t.d[b];}return J(.1)*c;}
 if(mode==5)return J(.01)*y[0]*y[0]/cubed_sphere::Power(r,1.5);if(mode==6)return J(.2)*cubed_sphere::Log(r+J(.17));return J(0);}
S ToS(const J&j){S q{};q.value=j.f;for(int a=0;a<3;++a){q.d[a]=j.d[a];for(int b=0;b<3;++b)q.dd[a][b]=j.h[a][b];}return q;}
S ScalarSample(Engine&engine,const V&state,const V&padded,size_t p,int field){const auto&g=engine.shift.grid;S q{};q.value=state[p*22+field];g.Derivatives(padded,field,p,q.d,q.dd);for(const auto&row:engine.supported_log_plans->Rows())if(row.active==p)return engine.supported_log_plans->Sample(row,state,22,field);return q;}
using W=std::array<Real,9>;
std::map<size_t,W> SparseWeights(Engine&engine,size_t p){const auto&g=engine.shift.grid;const size_t count=g.active.size();const Real h=Scale(g,p);std::map<size_t,W>out;
 for(const auto&row:engine.supported_log_plans->Rows())if(row.active==p){for(size_t j=0;j<row.donors.size();++j){V values(row.donors.size(),0);values[j]=1;h::SupportedRhoLogDerivative::Result r;if(!row.plan.Evaluate(values,engine.supported_log_plans->position,r))throw std::runtime_error("supported impulse");auto&w=out[row.donors[j]];for(int a=0;a<3;++a)w[a]=h*r.gradient[a];int f=3;for(int a=0;a<3;++a)for(int b=a;b<3;++b)w[f++]=h*h*r.hessian[a][b];}return out;}
 std::vector<int>reverse(g.count,-1);for(size_t q=0;q<count;++q)reverse[g.active[q]]=q;std::map<int,const Grid::Row*>halos;for(const auto&r:g.halos)halos[r.target]=&r;std::set<int>enriched;for(const auto&r:engine.log_halo_plans->rows)for(int target:r.targets)enriched.insert(target);
 auto add=[&](size_t id,const W&w,Real weight){auto&target=out[id];for(int f=0;f<9;++f)target[f]+=weight*w[f];};V impulse(g.count,0);
 for(int index:Stencil(g,p)){impulse[index]=1;Real d[3],dd[3][3];g.Derivatives(impulse,0,p,d,dd);impulse[index]=0;W w{};for(int a=0;a<3;++a)w[a]=h*d[a];int f=3;for(int a=0;a<3;++a)for(int b=a;b<3;++b)w[f++]=h*h*dd[a][b];if(reverse[index]>=0){add(reverse[index],w,1);continue;}if(enriched.count(index))throw std::runtime_error("query requires loghalo sparse weights not supported by this seven-query audit");const auto&row=*halos.at(index);Real sum=0;for(const auto&e:row.entries){if(reverse[e.point]<0)throw std::runtime_error("nonactive halo donor");sum+=e.weight;add(reverse[e.point],w,e.weight);}add(reverse[row.entries[0].point],w,1-sum-row.boundary_weight);
  if(row.boundary_weight){const auto x=row.boundary;const int owner=g.mesh.Owner(x.data()),n=g.n;if(owner<0||engine.scri->base[owner]<0)throw std::runtime_error("surface owner");Real q[3];g.mesh.Inverse(owner,x.data(),q);Real weights[2][6];int first[2];for(int a=0;a<2;++a){const Real t=n*q[a+1]-.5;first[a]=std::clamp(int(std::floor(t))-2,0,n-6);for(int i=0;i<6;++i){weights[a][i]=1;for(int j=0;j<6;++j)if(i!=j)weights[a][i]*=(t-first[a]-j)/Real(i-j);}}Real total=0;for(int k=0;k<6;++k)for(int j=0;j<6;++j){const Real weight=weights[0][j]*weights[1][k];total+=weight;add(count+engine.scri->base[owner]+first[0]+j+n*(first[1]+k),w,row.boundary_weight*weight);}add(count+engine.scri->base[owner]+first[0]+n*first[1],w,row.boundary_weight*(1-total));}
 }return out;}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;try{if(argc!=4)throw std::runtime_error("initial exact coefficient_functionals");auto g=MakeGrid();const auto exact=ReadExact(argv[2]);std::array<V,2>coefficient;for(auto&v:coefficient)v.resize(g.active.size());std::ifstream f(argv[3]);std::string magic;size_t count;f>>magic>>count;if(magic!="GLOBAL_BACKGROUND_FUNCTIONALS_V1"||count!=g.active.size())throw std::runtime_error("coefficient count");for(size_t p=0;p<count;++p){size_t id;f>>id>>coefficient[0][p]>>coefficient[1][p];if(!f||id!=p)throw std::runtime_error("coefficient row");}Engine engine(g.mesh,true,1e-10,4,true,true,0,6,true,2,.24,true,true,true,true,.24,1);engine.Initialize(0,false);engine.InitializeWormhole(argv[1],0,false);const auto padded=engine.Padded(engine.state);std::cout<<std::setprecision(17);
 for(size_t p:{size_t(0),size_t(1),size_t(126),size_t(127),size_t(5319),size_t(39340),size_t(7816)}){const auto sparse=SparseWeights(engine,p);const Real h=Scale(g,p);for(int field=0;field<2;++field){const auto old=ScalarSample(engine,engine.state,padded,p,field?18:0),truth=StoredExact(g.geometry[p].x,exact.at({0,p}),field);W delta{};for(int a=0;a<3;++a)delta[a]=h*(truth.d[a]-old.d[a]);int row=3;for(int a=0;a<3;++a)for(int b=a;b<3;++b)delta[row++]=h*h*(truth.dd[a][b]-old.dd[a][b]);W oldnorm{},newnorm{},constant{};for(size_t donor=0;donor<count+engine.scri->rows.size();++donor){auto found=sparse.find(donor);W weights{};if(found!=sparse.end())weights=found->second;for(int f=0;f<9;++f){oldnorm[f]+=std::abs(weights[f]);const Real w=weights[f]+(donor<count?coefficient[field][donor]*delta[f]:0);newnorm[f]+=std::abs(w);constant[f]+=w;}}std::cout<<"{\"point\":"<<p<<",\"field\":"<<field<<",\"sparse_base_donors\":"<<sparse.size()<<",\"all_active_and_scri_unknowns\":"<<count+engine.scri->rows.size()<<",\"base_gradient_L1\":"<<*std::max_element(oldnorm.begin(),oldnorm.begin()+3)<<",\"new_gradient_L1\":"<<*std::max_element(newnorm.begin(),newnorm.begin()+3)<<",\"base_hessian_L1\":"<<*std::max_element(oldnorm.begin()+3,oldnorm.end())<<",\"new_hessian_L1\":"<<*std::max_element(newnorm.begin()+3,newnorm.end())<<",\"constant_leak_max\":"<<std::abs(*std::max_element(constant.begin(),constant.end(),[](Real a,Real b){return std::abs(a)<std::abs(b);}))<<",\"complete_current_base_weights\":true}\n";}}
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=1;}Kokkos::finalize();return code;}
